pm.test("Статус ответа — 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Сервер возвращает status: ok", function () {
    const json = pm.response.json();
    pm.expect(json.status).to.eql("ok");
});


pm.test("Ответ имеет формат JSON", function () {
    const contentType = pm.response.headers.get("Content-Type");

    pm.expect(contentType).to.include("application/json");
});

pm.test("Несуществующий маршрут возвращает 404", function () {
    pm.response.to.have.status(404);
});

pm.test("Ошибка возвращается в формате JSON", function () {
    const contentType = pm.response.headers.get("Content-Type");
    pm.expect(contentType).to.include("application/json");
});

pm.test("POST на GET-маршрут возвращает 404", function () {
    pm.response.to.have.status(404);
});

pm.test("Сервер возвращает ошибку not_found", function () {
    const json = pm.response.json();
    pm.expect(json.error).to.eql("not_found");
});

pm.test("Заявка создана — 201", function () {
    pm.response.to.have.status(201);
});

const json = pm.response.json();

pm.test("Тип заявки — inspection", function () {
    pm.expect(json.type).to.eql("inspection");
});

pm.test("Статус заявки — new", function () {
    pm.expect(json.status).to.eql("new");
});

pm.test("У заявки есть ID", function () {
    pm.expect(json.id).to.be.a("string").and.not.empty;
});

if (pm.response.code === 201 && json.id) {
    pm.collectionVariables.set("requestId", json.id);
}

pm.test("Назначение инженера возвращает 200", function () {
    pm.response.to.have.status(200);
});

const json = pm.response.json();

pm.test("Заявка переведена в работу", function () {
    pm.expect(json.status).to.eql("in_progress");
});

pm.test("Инженер назначен", function () {
    pm.expect(json.assignee).to.eql("Engineer QA");
});

pm.test("ID заявки совпадает", function () {
    pm.expect(json.id).to.eql(pm.collectionVariables.get("requestId"));
});

pm.test("Закрытие заявки возвращает 200", function () {
    pm.response.to.have.status(200);
});

const json = pm.response.json();

pm.test("Статус заявки — done", function () {
    pm.expect(json.status).to.eql("done");
});

pm.test("Комментарий о закрытии сохранён", function () {
    pm.expect(json.closingComment).to.be.a("string").and.not.empty;
});

pm.test("Дата завершения заполнена", function () {
    pm.expect(json.completedAt).to.be.a("string").and.not.empty;
});

